import itertools
fac={'x':x,'v':v,'t':t,'st':np.sin(t),'ct':np.cos(t),'lv':np.log(v),'sv':np.sqrt(v)}
lib={'1':np.ones_like(x)}
for k in range(1,4):
    for combo in itertools.combinations_with_replacement(list(fac),k):
        arr=np.ones_like(x)
        for c_ in combo: arr=arr*fac[c_]
        lib['*'.join(combo)]=arr
for a in ['x','v','t']:
    for p in [2,3]:
        lib[f'{a}^{p}']=fac[a]**p
names=list(lib); print(len(names))
def fit(sel):
    B=np.column_stack([lib[n] for n in sel]); c,_,_,_=np.linalg.lstsq(B,dv_dt,rcond=None)
    return np.var(dv_dt-B@c)/np.var(dv_dt),c
sel=['1']
for k in range(10):
    best=min((fit(sel+[n])[0],n) for n in names if n not in sel)
